def get_bar(asset, dt, frequency, fields=None):
    engine_obj = engine_instance()
    current_date = time.strftime('%Y%m%d')
    if dt.strftime('%Y%m%d') == current_date:
        bars = engine_obj.real_quote_handler.get_bar(asset, frequency, fields)
        return bars
    else:
        bars = engine_obj.history_quote_handler.get_bar(asset, dt, frequency, fields)
        return bars
